<?php
declare(strict_types=1);session_start();
$base=__DIR__;foreach([$base.'/config/config.php',$base.'/config.php'] as$f){if(is_file($f)){require_once$f;break;}}require_once$base.'/includes/expediente360_helpers.php';if(!isset($pdo)||!($pdo instanceof PDO)){http_response_code(500);exit('PDO no disponible.');}
$cl= strtoupper(trim((string)($_GET['clasificacion']??'')));$estado=trim((string)($_GET['estado']??''));$qtxt=trim((string)($_GET['q']??''));
$where=['p.activo=1'];$vals=[];if(in_array($cl,['ACTIVISTA','SIMPATIZANTE'],true)){$where[]='COALESCE(p.clasificacion_actual,p.clasificacion_general)=?';$vals[]=$cl;}if($estado!==''){$where[]='p.estado=?';$vals[]=$estado;}if($qtxt!==''){$where[]='(p.nombre_completo LIKE ? OR p.cedula_normalizada LIKE ? OR p.telefono_principal LIKE ?)';$like='%'.$qtxt.'%';array_push($vals,$like,$like,$like);}
$W=implode(' AND ',$where);
$stats=['total'=>0,'activistas'=>0,'simpatizantes'=>0,'participantes'=>0,'no_rep'=>0,'inconsistencias'=>0];
try{$r=$pdo->query("SELECT COUNT(*) total,SUM(COALESCE(clasificacion_actual,clasificacion_general)='ACTIVISTA') activistas,SUM(COALESCE(clasificacion_actual,clasificacion_general)='SIMPATIZANTE') simpatizantes,SUM(es_asistente_general=1) participantes,SUM(rep_encontrado=0) no_rep FROM personas WHERE activo=1")->fetch(PDO::FETCH_ASSOC);$stats=array_merge($stats,array_map('intval',$r?:[]));}catch(Throwable$e){}
try{$stats['inconsistencias']=(int)$pdo->query("SELECT COUNT(*) FROM expediente360_inconsistencias WHERE estatus='PENDIENTE'")->fetchColumn();}catch(Throwable$e){}
$sql="SELECT p.*, (SELECT COUNT(*) FROM actividad_asistencias aa WHERE aa.persona_id=p.id AND aa.asistencia='asistio') actividades FROM personas p WHERE $W ORDER BY p.ultima_actividad_at DESC,p.nombre_completo ASC LIMIT 300";$st=$pdo->prepare($sql);$st->execute($vals);$people=$st->fetchAll(PDO::FETCH_ASSOC);
$estados=[];try{$estados=$pdo->query("SELECT DISTINCT estado FROM personas WHERE estado IS NOT NULL AND estado<>'' ORDER BY estado")->fetchAll(PDO::FETCH_COLUMN);}catch(Throwable$e){}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expediente 360°</title><style>:root{--o:#f28c18;--n:#111b2f;--bg:#f3f5f9;--mut:#70798c}*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial;background:var(--bg);color:#172033}.top{background:linear-gradient(135deg,#111b2f,#20345a);color:#fff;padding:24px 18px 72px}.wrap{max-width:1220px;margin:auto}.brand{font-weight:900;letter-spacing:.08em;color:#ffb05c}.title{font-size:38px;margin:8px 0}.sub{color:#cbd5e6}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-top:-48px}.card{background:#fff;border-radius:20px;padding:18px;box-shadow:0 14px 40px #14203816}.card b{display:block;font-size:28px;margin-top:7px}.orange b{color:var(--o)}.blue b{color:#2a66b7}.red b{color:#c43c3c}.filters{display:grid;grid-template-columns:1.2fr .8fr .8fr auto;gap:10px;margin:18px 0}.filters input,.filters select{width:100%;padding:13px;border:1px solid #dce1eb;border-radius:12px;background:#fff}.btn{border:0;background:var(--o);color:#fff;padding:13px 20px;border-radius:12px;font-weight:900}.table{background:#fff;border-radius:20px;padding:8px 18px;box-shadow:0 14px 40px #1420380d}.row{display:grid;grid-template-columns:1.8fr .8fr 1fr 1fr .7fr .5fr;gap:12px;align-items:center;padding:14px 4px;border-bottom:1px solid #edf0f5}.row.head{font-size:12px;text-transform:uppercase;color:var(--mut);font-weight:900}.name{font-weight:900}.meta{font-size:12px;color:var(--mut);margin-top:4px}.pill{display:inline-block;padding:6px 10px;border-radius:999px;font-size:12px;font-weight:900}.act{background:#fff0dc;color:#a65e00}.sim{background:#e7f2ff;color:#155b9a}.open{color:var(--o);font-weight:900;text-decoration:none}.warn{background:#fff1f1;color:#a12d2d}.empty{padding:30px;text-align:center;color:var(--mut)}@media(max-width:950px){.cards{grid-template-columns:repeat(3,1fr)}.row{grid-template-columns:1.6fr .8fr .8fr}.row>*:nth-child(4),.row>*:nth-child(5){display:none}}@media(max-width:620px){.top{padding:20px 14px 58px}.title{font-size:30px}.wrap{padding:0 14px}.cards{grid-template-columns:1fr 1fr;gap:9px}.card{padding:14px;border-radius:16px}.card b{font-size:23px}.filters{grid-template-columns:1fr}.table{padding:6px 12px}.row{grid-template-columns:1fr auto;gap:8px}.row.head{display:none}.row>*:nth-child(2),.row>*:nth-child(4),.row>*:nth-child(5){display:none}.row>*:nth-child(3){text-align:right}.row>*:nth-child(6){grid-column:2}.name:before{content:'◉ ';color:var(--o)}} </style></head><body><header class="top"><div class="wrap"><div class="brand">VPNACIONAL</div><h1 class="title">Expediente 360°</h1><div class="sub">Una persona · una cédula · una vinculación organizativa activa · historial completo</div></div></header><main class="wrap"><section class="cards"><div class="card orange"><span>Personas únicas</span><b><?=$stats['total']?></b></div><div class="card orange"><span>Activistas</span><b><?=$stats['activistas']?></b></div><div class="card blue"><span>Simpatizantes</span><b><?=$stats['simpatizantes']?></b></div><div class="card"><span>Con actividades</span><b><?=$stats['participantes']?></b></div><div class="card"><span>No REP</span><b><?=$stats['no_rep']?></b></div><div class="card red"><span>Inconsistencias</span><b><?=$stats['inconsistencias']?></b></div></section><form class="filters"><input name="q" value="<?=htmlspecialchars($qtxt)?>" placeholder="Buscar por cédula, nombre o teléfono"><select name="clasificacion"><option value="">Todas las clasificaciones</option><option <?=$cl==='ACTIVISTA'?'selected':''?>>ACTIVISTA</option><option <?=$cl==='SIMPATIZANTE'?'selected':''?>>SIMPATIZANTE</option></select><select name="estado"><option value="">Todos los estados</option><?php foreach($estados as$e):?><option <?=($estado===$e)?'selected':''?>><?=htmlspecialchars($e)?></option><?php endforeach;?></select><button class="btn">Filtrar</button></form><section class="table"><div class="row head"><span>Persona</span><span>Cédula</span><span>Clasificación</span><span>Territorio</span><span>Actividades</span><span></span></div><?php foreach($people as$p):$c=$p['clasificacion_actual']?:$p['clasificacion_general'];?><div class="row"><div><div class="name"><?=htmlspecialchars($p['nombre_completo']?:'SIN NOMBRE')?></div><div class="meta"><?=htmlspecialchars($p['telefono_principal']?:'Sin teléfono')?> · <?=htmlspecialchars($p['centro']?:'Sin centro electoral')?></div></div><span><?=htmlspecialchars($p['cedula_normalizada'])?></span><span><i class="pill <?=$c==='ACTIVISTA'?'act':'sim'?>"><?=htmlspecialchars($c?:'SIMPATIZANTE')?></i></span><span><?=htmlspecialchars(trim(($p['estado']??'').' · '.($p['municipio']??''),' ·'))?></span><strong><?=$p['actividades']?></strong><a class="open" href="expediente360_detalle.php?id=<?=$p['id']?>">Ver</a></div><?php endforeach;?><?php if(!$people):?><div class="empty">No se encontraron expedientes.</div><?php endif;?></section></main></body></html>